import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "refined",
  scrollAreaBlur: true,
  indicators: {
    sidebar: "hover",
    "button-group": "hover",
    "toggle-group": "hover",
    "checkbox-group": "hover",
  },
};

[data-skin="refined"] {
  --refined-surface-shadow:
    0 0 0 var(--control-rim-width) oklch(from var(--shadow-color) l c h / calc(0.06 * var(--ring-opacity))),
    0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size)) calc(-1px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.06 * var(--shadow-opacity))),
    0 calc(2px * var(--shadow-size)) calc(4px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.04 * var(--shadow-opacity)));
  --refined-solid-shadow:
    0 0 0 var(--control-rim-width) oklch(from var(--primary) l c h / calc(0.6 * var(--ring-opacity))),
    0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size)) calc(-1px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.4 * var(--shadow-opacity))),
    0 calc(2px * var(--shadow-size)) calc(4px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.18 * var(--shadow-opacity)));
}

:is(.dark [data-skin="refined"], [data-skin="refined"].dark) {
  --refined-surface-shadow:
    inset 0 1px var(--shadow-highlight), inset 0 0 0 var(--control-rim-width) var(--border),
    0 calc(2px * var(--shadow-size)) calc(4px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.1 * var(--shadow-opacity))),
    0 calc(8px * var(--shadow-size)) calc(8px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.1 * var(--shadow-opacity)));
  --refined-solid-shadow:
    inset 0 1px oklch(1 0 0 / calc(0.45 * var(--shadow-opacity))),
    0 0 0 var(--control-rim-width) oklch(from var(--primary) l c h / calc(0.55 * var(--ring-opacity))),
    0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.5 * var(--shadow-opacity)));
}

@layer components {
  [data-skin="refined"] :where([data-control-family="button"][data-variant="solid"]) {
    --cui-button-shadow: var(--refined-solid-shadow);
  }

  [data-skin="refined"] :where([data-control-family="button"][data-variant="surface"]) {
    --cui-button-background: var(--card);
    --cui-button-hover-background: var(--muted);
    --cui-button-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="button"][data-tone="danger"][data-variant="solid"]) {
    --cui-button-shadow:
      0 0 0 var(--control-rim-width) oklch(from var(--destructive) l c h / calc(0.25 * var(--ring-opacity))),
      0 calc(2px * var(--shadow-size)) calc(4px * var(--shadow-size))
      oklch(from var(--destructive) l c h / calc(0.12 * var(--shadow-opacity)));
  }

  [data-skin="refined"] :where([data-control-family="card"][data-slot="root"]) {
    --cui-card-radius: var(--radius-panel);
    --cui-card-border-width: 0px;
    --cui-card-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: var(--radius);
    --cui-field-background: var(--card);
    --cui-field-shadow: none;
  }

  [data-skin="refined"] :where([data-control-family="code"][data-slot="root"]) {
    --cui-code-background: var(--card);
    --cui-code-border-color: transparent;
    --cui-code-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="tabs"][data-slot="root"]) {
    --cui-tabs-list-background: var(--muted);
    --cui-tabs-list-shadow: none;
    --cui-tabs-indicator-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="range"][data-slot="root"]) {
    --cui-range-thumb-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="switch"][data-slot="root"]) {
    --cui-switch-thumb-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="sidebar"][data-slot="wrapper"]) {
    --cui-sidebar-inset-shadow: none;
  }
}

[data-skin="refined"][data-skin] {
  --font-sans: var(--font-inter, "Inter"), ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: var(--font-jetbrains-mono, "JetBrains Mono"), ui-monospace, SFMono-Regular, Menlo, monospace;
  --text-label: 0.75rem;
  --text-heading-4--font-weight: 500;
  --text-heading-3--font-weight: 500;
  --text-heading-2--font-weight: 500;
  --text-heading-1--font-weight: 500;
  --text-heading-1--letter-spacing: -0.025em;
  --text-display: 2rem;
  --text-display--font-weight: 500;
  --text-display--letter-spacing: -0.03em;

  --background: oklch(0.985 0 0);
  --foreground: oklch(0.205 0 0);
  --card: oklch(1 0 0);
  --card-foreground: var(--foreground);
  --popover: var(--card);
  --popover-foreground: var(--foreground);
  --primary: var(--foreground);
  --primary-foreground: var(--background);
  --secondary: oklch(0.95 0 0);
  --secondary-foreground: var(--foreground);
  --muted: oklch(0.96 0 0);
  --muted-foreground: oklch(0.52 0 0);
  --accent: oklch(0.955 0 0);
  --accent-foreground: var(--foreground);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.922 0 0 / var(--ring-opacity));
  --input: oklch(0.922 0 0);
  --ring: oklch(0.5 0 0);
  --focus-ring: var(--ring);
  --primary-text: var(--foreground);
  --canvas: var(--background);

  --popover-opacity: 1;
  --backdrop-blur-popover: 0px;
  --overlay-opacity: 0.2;
  --backdrop-blur-overlay: 0px;
  --scroll-fade-size: 2rem;
  --shadow-color: oklch(0 0 0);
  --shadow-highlight: oklch(1 0 0 / 0.6);
  --shadow-size: 1;
  --shadow-opacity: 1;

  --radius: 0.625rem;
  --radius-control: calc(var(--radius) * 2);
  --radius-field: var(--radius);
  --radius-panel: calc(var(--radius) * 1.4);
  --radius-scene: calc(var(--radius) * 1.8);
  --radius-popup-item: calc(var(--radius) * 0.8);
  --popover-padding: 0.25rem;
  --padding-x: 0.875rem;
  --padding-y: 0.5rem;
  --control-h: 2rem;

  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --ease-emphasized: cubic-bezier(0.23, 1, 0.32, 1);
  --duration-fast: 150ms;
  --duration-base: 200ms;
  --duration-slow: 300ms;
}

.dark [data-skin="refined"][data-skin],
[data-skin="refined"][data-skin].dark {
  --background: oklch(0.17 0 0);
  --foreground: oklch(0.945 0 0);
  --card: oklch(0.205 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: var(--card);
  --secondary: oklch(0.269 0 0);
  --muted: oklch(0.24 0 0);
  --muted-foreground: oklch(0.7 0 0);
  --accent: oklch(0.269 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.17 0 0);
  --border: oklch(0.32 0 0 / var(--ring-opacity));
  --input: oklch(0.36 0 0);
  --ring: oklch(0.7 0 0);
  --shadow-highlight: oklch(1 0 0 / 0.03);
}
